import { vi, test, expect, beforeEach } from 'vitest'
import { createPinia, setActivePinia } from 'pinia'

// 远程模式依赖真实后端；这里把 request 替换为可控 mock，验证
// 1) inspectionRowToRecord 按 bizState 映射 status（0=待提交，1/2=已提交）
// 2) 历史记录「待提交 / 已提交归档」筛选在远程模式真实生效（见禅道 bug 6418）
vi.mock('../src/utils/request', async () => {
  const actual = await vi.importActual<typeof import('../src/utils/request')>('../src/utils/request')
  return { ...actual, request: vi.fn() }
})

import { createFloodStore } from '../src/stores/flood'
import { request } from '../src/utils/request'

const memory = new Map<string, unknown>()
const storage = {
  get: (key: string) => memory.get(key),
  set: (key: string, value: unknown) => { memory.set(key, structuredClone(value)) },
}
const requestMock = request as unknown as ReturnType<typeof vi.fn>

// 一页里混入：1 条待提交(bizState=0)、2 条已提交(bizState=1)、1 条备案完成(bizState=2)
function inspectionPage() {
  return {
    rows: [
      { inspectionId: 1, inspectionStage: '2', bizState: '0', subject: 'property', createTime: '2026-11-01T00:00:00Z' },
      { inspectionId: 2, inspectionStage: '2', bizState: '1', subject: 'property', createTime: '2026-11-02T00:00:00Z' },
      { inspectionId: 3, inspectionStage: '2', bizState: '1', subject: 'property', createTime: '2026-11-03T00:00:00Z' },
      { inspectionId: 4, inspectionStage: '2', bizState: '2', subject: 'property', createTime: '2026-11-04T00:00:00Z' },
    ],
    total: 4,
  }
}

beforeEach(() => {
  memory.clear()
  setActivePinia(createPinia())
  requestMock.mockReset()
  requestMock.mockImplementation(async (url: string) => {
    const u = String(url)
    if (u.includes('/inspection/page')) return inspectionPage()
    if (u.includes('/rescue/page')) return { rows: [], total: 0 }
    if (/\/inspection\/\d+$/.test(u)) return { inspectionId: 1, inspectionStage: '2', bizState: '0', subject: 'property' }
    if (/\/rescue\/\d+$/.test(u)) return { rescueId: 1 }
    return { rows: [], total: 0 }
  })
})

test('远程模式：bizState 映射到 status，待提交与已提交不再混为一谈', async () => {
  const store = createFloodStore(storage, 'remote')()

  // 待提交筛选只应拿到 bizState=0 的那一条
  const draft = await store.fetchHistoryPage({ pageNum: 1, pageSize: 10, kinds: ['pre'], status: 'draft' })
  expect(draft.total).toBe(1)
  expect(draft.items).toHaveLength(1)
  expect(draft.items[0].id).toBe('1')
  expect(draft.items[0].status).toBe('draft')

  // 已提交归档应拿到 bizState=1 与 2（共 3 条），且不含待提交
  const submitted = await store.fetchHistoryPage({ pageNum: 1, pageSize: 10, kinds: ['pre'], status: 'submitted' })
  expect(submitted.total).toBe(3)
  expect(submitted.items).toHaveLength(3)
  expect(submitted.items.every(i => i.status === 'submitted')).toBe(true)
  expect(submitted.items.find(i => i.id === '1')).toBeUndefined()

  // 全部工单 = 待提交 + 已提交
  const all = await store.fetchHistoryPage({ pageNum: 1, pageSize: 10, kinds: ['pre'], status: 'all' })
  expect(all.total).toBe(4)
})

